	dUTF8 = dataset{
		Name:   "bad\xffutf8",
		Refs:   map[string]string{"K\xfe": "x.y"},
		Values: map[string]string{"K\xfe": "v\xc3(\xf0\x28\x8c\xbc"},
	}
	allData = []dataset{dApp, dMasked, dSpecial, dEmpty, dOrder}
